return $input.all().map(({ json }) => {
  const cuerpo = json.plantilla_cuerpo || 'Hola {{nombres}}, te extranamos en el gym! Aqui te esperamos.';
  const vars = { nombres: json.nombres || '', apellidos: json.apellidos || '', plan: '', fecha_fin: '', dias_restantes: '', monto: '' };
  const texto = String(cuerpo).replace(/\{\{\s*(\w+)\s*\}\}/g, (_, k) => (vars[k] ?? ''));
  const numero = String(json.telefono || '').replace(/\D/g, '');
  return { json: { socio_id: json.socio_id, clave: 'te_extranamos', numero, texto } };
}).filter((i) => i.json.numero);

const esc = (s) => String(s ?? '').replace(/'/g, "''");
return $('Render').all().map(({ json: r }) => {
  const sql = `INSERT INTO mensajes_enviados (socio_id, telefono, canal, plantilla_clave, contenido, estado, enviado_en, referencia_tipo) VALUES ('${esc(r.socio_id)}', '${esc(r.numero)}', 'whatsapp', 'te_extranamos', '${esc(r.texto)}', 'enviado', now(), 'asistencia')`;
  return { json: { sql } };
});
